INSERT INTO progression_entities(player_id,entity_category,entity_key) SELECT id,'player','player_core' FROM players WHERE NOT EXISTS (SELECT 1 FROM progression_entities pe WHERE pe.player_id=players.id AND pe.entity_category='player' AND pe.entity_key='player_core');
