USE stargatewars;

CREATE TABLE IF NOT EXISTS progression_tiers (id TINYINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tier_number TINYINT UNSIGNED NOT NULL UNIQUE,tier_name VARCHAR(80) NOT NULL,unlock_score BIGINT UNSIGNED NOT NULL,description VARCHAR(255) NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS progression_levels (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tier_id TINYINT UNSIGNED NOT NULL,level_number TINYINT UNSIGNED NOT NULL,global_level SMALLINT UNSIGNED NOT NULL UNIQUE,xp_cost BIGINT UNSIGNED NOT NULL,metal_cost BIGINT UNSIGNED NOT NULL DEFAULT 0,crystal_cost BIGINT UNSIGNED NOT NULL DEFAULT 0,naquadah_cost BIGINT UNSIGNED NOT NULL DEFAULT 0,food_cost BIGINT UNSIGNED NOT NULL DEFAULT 0,water_cost BIGINT UNSIGNED NOT NULL DEFAULT 0,energy_cost BIGINT UNSIGNED NOT NULL DEFAULT 0,dark_matter_cost BIGINT UNSIGNED NOT NULL DEFAULT 0,effect_percent DECIMAL(8,3) NOT NULL DEFAULT 0,build_seconds INT UNSIGNED NOT NULL DEFAULT 60,FOREIGN KEY(tier_id) REFERENCES progression_tiers(id) ON DELETE CASCADE,UNIQUE KEY uq_tier_level(tier_id,level_number)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS progression_entities (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,player_id INT UNSIGNED NOT NULL,entity_category VARCHAR(30) NOT NULL,entity_key VARCHAR(100) NOT NULL,tier_number TINYINT UNSIGNED NOT NULL DEFAULT 1,level_number TINYINT UNSIGNED NOT NULL DEFAULT 1,experience BIGINT UNSIGNED NOT NULL DEFAULT 0,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(player_id) REFERENCES players(id) ON DELETE CASCADE,UNIQUE KEY uq_player_entity(player_id,entity_category,entity_key),KEY idx_entity_level(entity_category,tier_number,level_number)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS progression_prerequisites (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,entity_category VARCHAR(30) NOT NULL,entity_key VARCHAR(100) NOT NULL,required_category VARCHAR(30) NOT NULL,required_key VARCHAR(100) NOT NULL,required_tier TINYINT UNSIGNED NOT NULL DEFAULT 1,required_level TINYINT UNSIGNED NOT NULL DEFAULT 1,UNIQUE KEY uq_progression_requirement(entity_category,entity_key,required_category,required_key)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS progression_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,player_id INT UNSIGNED NOT NULL,entity_category VARCHAR(30) NOT NULL,entity_key VARCHAR(100) NOT NULL,tier_before TINYINT UNSIGNED NOT NULL,level_before TINYINT UNSIGNED NOT NULL,tier_after TINYINT UNSIGNED NOT NULL,level_after TINYINT UNSIGNED NOT NULL,cost_payload JSON NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(player_id) REFERENCES players(id) ON DELETE CASCADE,KEY idx_progress_event_player(player_id,created_at)) ENGINE=InnoDB;



